var DIRECTIONS = ["UP", "RIGHT", "DOWN", "LEFT"];
var DIRECTION_VECTORS = {
  UP: { x: 0, y: -1 },
  DOWN: { x: 0, y: 1 },
  LEFT: { x: -1, y: 0 },
  RIGHT: { x: 1, y: 0 }
};
var posKey = (p) => `${p.x},${p.y}`;
var samePos = (a, b2) => a.x === b2.x && a.y === b2.y;
var addPos = (a, b2, times = 1) => ({
  x: a.x + b2.x * times,
  y: a.y + b2.y * times
});
var step = (p, dir, times = 1) => addPos(p, DIRECTION_VECTORS[dir], times);
var manhattan = (a, b2) => Math.abs(a.x - b2.x) + Math.abs(a.y - b2.y);
var chebyshev = (a, b2) => Math.max(Math.abs(a.x - b2.x), Math.abs(a.y - b2.y));
function alignedDirection(from, to2) {
  if (samePos(from, to2)) return null;
  if (from.x === to2.x) return to2.y < from.y ? "UP" : "DOWN";
  if (from.y === to2.y) return to2.x < from.x ? "LEFT" : "RIGHT";
  return null;
}
function dominantDirection(from, to2) {
  const dx = to2.x - from.x;
  const dy = to2.y - from.y;
  if (dx === 0 && dy === 0) return null;
  if (Math.abs(dx) >= Math.abs(dy)) return dx < 0 ? "LEFT" : "RIGHT";
  return dy < 0 ? "UP" : "DOWN";
}
var isHorizontal = (dir) => dir === "LEFT" || dir === "RIGHT";
