function executeCommand(ctx, command) {
  if (ctx.state.outcome) return fail("BATTLE_OVER", "The battle is over.");
  if (ctx.state.phase !== "PLAYER") return fail("NOT_PLAYER_TURN", "Not the player turn.");
  if (ctx.state.pendingCast && command.type !== "SILENCE_RESPONSE") return fail("INVALID_TARGET", "Hay una ventana de respuesta abierta.");
  if (ctx.state.player.pendingCardChoice && command.type !== "RESOLVE_CARD_CHOICE")
    return fail("INVALID_TARGET", "Completa primero la elecci\xF3n de carta pendiente.");
  switch (command.type) {
    case "REDEMPTION_SUPPORT":
      return redemptionSupport(ctx, command.unitId, command.targetId, command.action);
    case "SILENCE_RESPONSE": {
      const result = resolveSilence(ctx, command);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "RESOLVE_CARD_CHOICE":
      return resolveCardChoice(ctx, command.choiceUid);
    case "LEGENDARY_STEP": {
      const result = legendaryStep(ctx, command.to);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "MOVE_UNIT": {
      const result = moveUnit(ctx, command.unitId, command.to);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "SEARCH_SUMMON": {
      const result = playCard(ctx, command.cardUid, null, command.choiceUid);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "PLAY_CARD": {
      const result = playCard(ctx, command.cardUid, command.target, void 0, command.secondary, command.wallOrientation);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "COMMIT_RITUAL_PIECE":
      return commitRitualPiece(ctx, command.cardUid);
    case "RELEASE_RITUAL_PIECE":
      return releaseRitualPiece(ctx, command.cardUid);
    case "ACTIVATE_RITUAL": {
      const result = activateRitual(ctx, command.ritualId, command.target);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "INTERACT": {
      if (ctx.state.duel) return fail("UNKNOWN_MECHANISM", "No mechanisms in PvP.");
      const result = interact(ctx, command.mechanismId);
      if (result.ok) updateObjectives(ctx);
      return result;
    }
    case "END_TURN": {
      const discard = checkEndTurnDiscard(ctx.state, command.discardUid);
      if (!discard.ok) return discard;
      discardForHandLimit(ctx, command.discardUid);
      if (ctx.state.duel) endDuelTurn(ctx);
      else endPlayerTurnAndRunRound(ctx);
      return OK;
    }
  }
}

