function legacySnapshot(record, run) {
  const cohort = record.storyCohorts?.[`${run.campaignId}:${run.heroId}`];
  if (!cohort || cohort.closed) return null;
  if (lb(JSON.parse(cohort.runJson).run) !== lb(run) || run.status !== "IN_BATTLE") throw Error("Invalid sealed Story encounter");
  if (!cohort.snapshotJson) throw Error("Missing sealed Story snapshot");
  const saved = JSON.parse(cohort.snapshotJson);
  if (saved.rules !== nb || lb(saved.run) !== lb(run)) throw Error("Invalid sealed Story rules");
  return saved;
}
function publicLegacyCampaigns(record) {
  const result = {};
  if (record) for (const run of [...Object.values(record.runs), ...Object.values(record.worldRuns).flatMap((x) => Object.values(x))]) {
    if (!run) continue;
    const saved = legacySnapshot(record, run);
    if (saved) result[`${run.campaignId}:${run.heroId}`] = { rules: saved.rules, runSeed: run.seed, encounterId: run.currentEncounterId, profile: saved.profile, deckPinned: saved.deckPinned };
  }
  return result;
}
function verifyLegacyCampaign(record, run, proof) {
  const snapshot = legacySnapshot(record, run);
  return snapshot ? snapshot.deckPinned ? ib(snapshot.profile, snapshot.run, proof) : { ok: false, error: "The admitted legacy encounter needs a legal40-card deck before retry" } : null;
}
