var CONTENT_RELEASE = "winter-dominion-1";
var PREVIOUS_CONTENT_RELEASE = "darkness-expanded-1";
var LEGACY_CONTENT_RELEASE = "thunder-release-2";
var RELEASES = [LEGACY_CONTENT_RELEASE, "beasts-release-1", "scout-siege-release-1", "market-boxes-release-1", "frozen-battlefield-3", "winter-heart-2", "competitive-zones-1", "dark-light-1", PREVIOUS_CONTENT_RELEASE, CONTENT_RELEASE];
