var DAILY_FIRST_WIN_CRYSTALS = 40;
var ASCENT_CRYSTAL_MILESTONES = {
  3: 30,
  5: 40,
  9: 50,
  10: 100
};
var TEMPLE_CRYSTAL_MILESTONES = {
  2: 20,
  5: 30,
  9: 30
};
var CAMPAIGN_CRYSTAL_MILESTONES = {
  ascent: ASCENT_CRYSTAL_MILESTONES,
  temple: TEMPLE_CRYSTAL_MILESTONES
};

// qa/story-versioning-20261125/winter-source/server/src/economy.ts
var rewardDay = (now) => new Date(now).toISOString().slice(0, 10);
function victoryCrystalStatements(db2, userId, now, victory, newId2) {
  const rewards = [
    {
      transactionId: newId2(),
      reason: "DAILY_FIRST_WIN",
      amount: DAILY_FIRST_WIN_CRYSTALS,
      referenceId: rewardDay(now)
    }
  ];
  const campaign = WORLD_CAMPAIGNS[victory.campaignId];
  const index = campaign ? encounterOrder(campaign).findIndex((e) => e.id === victory.encounterId) + 1 : 0;
  const milestone = CAMPAIGN_CRYSTAL_MILESTONES[victory.campaignId]?.[index];
  if (!victory.skirmish && campaign && milestone) {
    rewards.push({
      transactionId: newId2(),
      reason: "CAMPAIGN_MILESTONE",
      amount: milestone,
      referenceId: `${victory.heroId}:${victory.campaignId}:${victory.encounterId}`
    });
  }
  const statements = rewards.map((reward2) => {
    const history = reward2.reason === "CAMPAIGN_MILESTONE" ? ` AND NOT EXISTS (SELECT 1 FROM tactics_reward_log WHERE user_id = ? AND COALESCE(hero_id, 'mage') = ? AND campaign_id = ? AND encounter_id = ? AND event IN ('OFFERED','NO_DROP','CLAIMED'))` : "";
    return db2.prepare(
      `INSERT INTO tactics_wallet_ledger (transaction_id,user_id,currency_id,amount_delta,balance_before,balance_after,reason,reference_id,note,created_at)
      SELECT ?,?,?,?,b,b+?,?,?,?,? FROM (SELECT COALESCE((SELECT balance FROM tactics_wallets WHERE user_id=? AND currency_id=?),0) AS b)
      WHERE NOT EXISTS (SELECT 1 FROM tactics_wallet_ledger WHERE user_id=? AND currency_id=? AND reason=? AND reference_id=?)${history}`
    ).bind(
      reward2.transactionId,
      userId,
      PREMIUM_CURRENCY_ID,
      reward2.amount,
      reward2.amount,
      reward2.reason,
      reward2.referenceId,
      reward2.reason === "DAILY_FIRST_WIN" ? "Primera victoria del d\xEDa (UTC)" : `Hito de ${campaign.name}: ${index}`,
      now,
      userId,
      PREMIUM_CURRENCY_ID,
      userId,
      PREMIUM_CURRENCY_ID,
      reward2.reason,
      reward2.referenceId,
      ...history ? [userId, victory.heroId, victory.campaignId, victory.encounterId] : []
    );
  });
  return { statements, rewards };
}
async function creditedRewards(db2, userId, rewards) {
  const paid = [];
  for (const r of rewards)
    if (await db2.prepare("SELECT 1 FROM tactics_wallet_ledger WHERE user_id=? AND transaction_id=?").bind(userId, r.transactionId).first())
      paid.push(r);
  return paid;
}

