  const heroes = [...new Set(available)];
  if (!heroes.length) throw Error("NO_PLAYABLE_BOT_CHAMPION");
  const repeated = recent.length >= 2 && recent[0] === recent[1] ? recent[0] : null;
  const weights = heroes.map((id2) => id2 === repeated ? 0.2 : 1), total = weights.reduce((a, b2) => a + b2, 0);
