function botDifficulty(rp2, seed, higherBps = BOT_HIGHER_LEVEL_BPS) {
  const chance = Number.isFinite(higherBps) ? Math.max(0, Math.min(1e4, Math.round(higherBps))) : BOT_HIGHER_LEVEL_BPS;
  let n = (seed ^ 2366825559) >>> 0;
  n = Math.imul(n ^ n >>> 16, 2146121005) >>> 0;
  n = Math.imul(n ^ n >>> 15, 2221713035) >>> 0;
  const roll = ((n ^ n >>> 16) >>> 0) / 4294967296;
  const baseLevel = rankFor(rp2).tierIndex;
  const promoted = roll < chance / 1e4;
  return {
    version: BOT_DIFFICULTY_MIX_VERSION,
    baseLevel,
    higherBps: chance,
    promoted,
    level: baseLevel + Number(promoted)
  };
}
