    kind: "BOT",
    id: id2,
    name: `${names[n % names.length]} ${titles[Math.floor(n / names.length) % titles.length]} \xB7 IA`,
    heroId: ["mage", "summoner", "shapeshifter"][Math.floor(n / 48) % 3],
    personality: BOT_PERSONALITIES[Math.floor(n / 144) % 6],
    level: difficultyMix.level,
