async function masteryRoute(request, env, caller, now) {
  const path = new URL(request.url).pathname.replace(/\/+$/, "");
  if (path !== "/api/tactics/mastery" && path !== "/api/tactics/mastery/title")
    return null;
  const route2 = `${request.method} ${path.endsWith("/title") ? "title" : "mastery"}`;
  if (route2 !== "GET mastery" && route2 !== "PUT title")
    return error(405, "BAD_METHOD", "M\xE9todo no permitido.");
  if (!masteryAllowed(env, caller.username)) {
    if (route2 === "GET mastery") return json({ enabled: false });
    return error(
      403,
      "MASTERY_DISABLED",
      "La maestr\xEDa todav\xEDa no est\xE1 disponible."
    );
  }
  const db2 = env.DB;
  const xp = await xpByChampion(db2, caller.userId);
  if (route2 === "PUT title") {
    let body;
    try {
      const raw = await request.text();
      if (raw.length > 512)
        return error(413, "TOO_LARGE", "Solicitud demasiado grande.");
      body = JSON.parse(raw || "{}");
    } catch {
      return error(400, "BAD_REQUEST", "Cuerpo inv\xE1lido.");
    }
    if (body.titleId === null) {
      await db2.prepare("DELETE FROM tactics_profile_titles WHERE user_id = ?").bind(caller.userId).run();
    } else {
      const title = titleById(body.titleId);
      const ranked2 = title ? void 0 : rankedTitleById(body.titleId);
      if (!title && !ranked2)
        return error(422, "UNKNOWN_TITLE", "T\xEDtulo desconocido.");
      if (title && masteryFor(xp[title.championId] ?? 0).level < title.requiredMastery)
        return error(
          403,
          "TITLE_LOCKED",
          "Todav\xEDa no has desbloqueado este t\xEDtulo."
        );
      if (ranked2 && !await ownsRankedTitle(db2, caller.userId, ranked2.id))
        return error(
          403,
          "TITLE_LOCKED",
          "Todav\xEDa no has desbloqueado este t\xEDtulo."
        );
      await db2.prepare(
        "INSERT INTO tactics_profile_titles (user_id, title_id, updated_at) VALUES (?, ?, ?) ON CONFLICT (user_id) DO UPDATE SET title_id = excluded.title_id, updated_at = excluded.updated_at"
      ).bind(caller.userId, (title ?? ranked2).id, now).run();
    }
  }
  const equipped = await equippedTitle(db2, caller.userId);
  const { results: rewards } = await db2.prepare(
    "SELECT hero_id, level, crystals, reached_at FROM tactics_mastery_rewards WHERE user_id = ? ORDER BY hero_id, level"
  ).bind(caller.userId).all();
  return json({
    enabled: true,
    config: masteryPublicConfig(),
    champions: Object.fromEntries(
      MASTERY_CHAMPIONS.map((id2) => [
        id2,
        { xp: xp[id2], level: masteryFor(xp[id2]).level }
      ])
    ),
    // Display names are NOT sent: the client resolves them from the catalog by id (titleName).
    titles: MASTERY_TITLES.map((t) => ({
      ...t,
      unlocked: masteryFor(xp[t.championId] ?? 0).level >= t.requiredMastery,
      equipped: t.id === equipped
    })),
    equippedTitleId: equipped,
    rewards: rewards.map((r) => ({
      heroId: r.hero_id,
      level: r.level,
      crystals: r.crystals,
      reachedAt: r.reached_at
    }))
  });
}

